import fs from "node:fs";

import { sample, uniqueName, expect, test } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("documents from another tenant are invisible", { tag: "@DOC-07" }, async ({ apiAs }) => {
    // Background: signed in as a Northwind member, with a draft vendor
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Northwind Draft"),
        category: "services",
        contact_email: `draft-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);

    // Arrange: a document exists in the Globex Procurement tenant
    const globex = await apiAs("otherTenant");
    const globexVendorRes = await globex.post("/api/vendors", {
      data: {
        name: uniqueName("Globex Vendor"),
        category: "services",
        contact_email: `globex-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(globexVendorRes.status(), await globexVendorRes.text()).toBe(201);
    const globexVendor = await globexVendorRes.json();

    const uploadRes = await globex.post(`/api/vendors/${globexVendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9.txt",
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample("w9.txt")),
        },
      },
    });
    expect(uploadRes.status(), await uploadRes.text()).toBe(201);
    const foreignDocument = await uploadRes.json();

    // Act: the Northwind member requests that document by id
    const res = await member.get(`/api/documents/${foreignDocument.id}`);

    // Assert
    const body = await res.text();
    expect(res.status(), body).toBe(404);
    expect(JSON.parse(body).error.code, body).toBe("document_not_found");
  });
});
